const scenes=[{id:'storm',name:'Supercell & hail',label:'CONCEPTUAL GREAT PLAINS STORM',tip:'One storm, six different stories. The hook suggests storm organization; investigate velocity and CC together.'},{id:'bats',name:'Bats leaving a roost',label:'BIOLOGICAL ECHO DEMONSTRATION',tip:'An expanding ring can be animals leaving a roost. Check timing, origin, and polarimetric clues.'},{id:'chaff',name:'Chaff drifting downwind',label:'NON-WEATHER ECHO DEMONSTRATION',tip:'Chaff can resemble rain in reflectivity, but low CC and independent observations help distinguish it.'},{id:'sun',name:'Sun interference',label:'RECEIVER INTERFERENCE DEMONSTRATION',tip:'A narrow radial spike points back to the radar. Compare scan time and the direction of sunrise or sunset.'},{id:'ap',name:'Anomalous propagation',label:'GROUND RETURN DEMONSTRATION',tip:'A beam bent toward the ground can illuminate terrain. Compare other radars, tilts, and surface observations.'}];
