let state={page:'explore',scene:'storm',product:'ref',frame:45,playing:false,compare:false,probe:null};let timer=null,raf=null;
const pageHead=(num,title,lead,pill='LEARN BY DOING')=>`<div class="section-top"><span class="eyebrow">THE FIELDGUIDE <span class="dot">/</span> ${num}</span><span class="pill">${pill}</span></div><h1>${title}</h1><p class="lead">${lead}</p>`;
function go(page){if(state.page==='quiz'&&answered&&!quizDone){qi++;answered=false;if(qi>=questions.length)quizDone=true;}if(timer)clearInterval(timer);timer=null;state.playing=false;state.page=page;$$('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false')});render();window.scrollTo({top:0,behavior:'instant'});}
function render(){const pages={explore:explore,basics:basics,doppler:doppler,beam:beam,cases:caseList,products:productPage,quiz:quiz,library:library};$('#page').innerHTML=pages[state.page]();bind();if(state.page==='explore')bindExplorer();if(state.page==='doppler')drawDoppler();if(state.page==='beam')drawBeam();if(state.page==='cases')drawCaseArts();}
function bind(){$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));}
$$('nav button').forEach(b=>b.onclick=()=>go(b.dataset.page));
function radarHTML(id='radar'){return `<div class="radar-area"><div class="toolbar"><strong id="canvas-title">${products.find(p=>p.id===state.product).name.toUpperCase()}</strong><span>ILLUSTRATIVE SCAN <button class="square" id="expand" aria-label="Expand radar workspace">⛶</button></span></div><div class="radar-wrap"><canvas id="${id}" role="img" aria-label="Interactive simulated radar. Use the product buttons and scenario selector to explore. Click or tap to inspect a sample." tabindex="0"></canvas><div class="map-tag"><b id="scene-tag">${scenes.find(s=>s.id===state.scene).label}</b><br>NOT LIVE DATA · SCHEMATIC GEOGRAPHY</div><div class="map-north">N<br>↑</div><div class="map-hint">+ CLICK OR TAP AN ECHO TO INSPECT</div></div><div class="legend" id="legend"></div><div class="playbar"><button id="play" aria-label="Play teaching animation">▶</button><input id="timeline" aria-label="Simulation time" type="range" min="0" max="100" value="${state.frame}"><small id="frame-label">FRAME ${state.frame}/100</small></div></div>`;}
function explore(){return `<div class="section-top"><span class="eyebrow">THE FIELDGUIDE <span class="dot">/</span> 01 RADAR EXPLORER</span><span class="pill">SCIENCE, WITHOUT THE STATIC</span></div><div class="title-line"><div><h1>See the <em>unseen.</em></h1><p class="lead">There’s a whole world inside a radar echo.<br>Change the view. Follow the clues. Learn what’s really in the sky.</p></div><div class="tiny-note">NO EXPERIENCE REQUIRED.<br>JUST A LITTLE CURIOSITY. ↓</div></div><div class="lab panel" id="workspace">${radarHTML()}<div class="control-panel"><div><label for="scenario">01 / CHOOSE A SCENE</label><select id="scenario">${scenes.map(s=>`<option value="${s.id}" ${state.scene===s.id?'selected':''}>${s.name}</option>`).join('')}</select><p class="tip">Synthetic learning scenes.<br>Real cases in Unusual echoes.</p></div><div class="control-block"><span class="label">02 / CHANGE YOUR LENS</span><div class="product-buttons">${products.map(p=>`<button data-product="${p.id}" class="${p.id===state.product?'active':''}" aria-pressed="${p.id===state.product}">${p.code}<small>${p.short}</small></button>`).join('')}</div></div><div class="info"><span class="eyebrow">WHAT YOU’RE SEEING</span><h3 id="product-question"></h3><p id="product-description"></p><div class="callout" id="scene-tip"></div><div class="inspect" id="probe" aria-live="polite">NO SAMPLE SELECTED<br>Tap the map to investigate.</div></div></div></div><div class="row space"><button class="button secondary" id="compare">${state.compare?'Close comparison':'Compare two products ↗'}</button><button class="text-button" data-go="products">All products explained →</button></div><div id="comparison"></div><div class="section-heading"><h2>Your next discovery</h2><button class="text-button" data-go="basics">Start with the basics →</button></div><div class="next-grid"><button class="next-card" data-go="doppler"><span class="number">THE DOPPLER LAB</span><span class="arrow">↗</span><h3>Red. Green. What does it mean?</h3><p>Move the wind. Watch the measurement change.</p></button><button class="next-card" data-go="cases"><span class="number">UNUSUAL ECHOES</span><span class="arrow">↗</span><h3>That’s definitely not rain.</h3><p>Bats, chaff, and other documented surprises.</p></button><button class="next-card" data-go="beam"><span class="number">INSIDE THE BEAM</span><span class="arrow">↗</span><h3>Why distance changes everything.</h3><p>Raise the scan. Explore what radar misses.</p></button></div>`;}
function setLegend(el,p){el.innerHTML=`<div class="legend-top"><span>${p.name.toUpperCase()}</span><span>${p.unit} · TEACHING PALETTE</span></div><div class="colorbar" style="background:linear-gradient(to right,${p.colors.join(',')})"></div><div class="ticks">${p.ticks.map(t=>`<span>${t}</span>`).join('')}</div>`;}
function bindExplorer(){updateExplorer();$('#scenario').onchange=e=>{state.scene=e.target.value;state.probe=null;updateExplorer()};$$('[data-product]').forEach(b=>b.onclick=()=>{state.product=b.dataset.product;updateExplorer()});$('#timeline').oninput=e=>{state.frame=+e.target.value;updateExplorer()};$('#play').onclick=()=>{state.playing=!state.playing;$('#play').textContent=state.playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',state.playing?'Pause teaching animation':'Play teaching animation');if(timer)clearInterval(timer);if(state.playing)timer=setInterval(()=>{state.frame=(state.frame+1)%101;$('#timeline').value=state.frame;updateExplorer()},140)};$('#expand').onclick=()=>{$('#workspace').classList.toggle('full-lab');$('#expand').textContent=$('#workspace').classList.contains('full-lab')?'×':'⛶';requestAnimationFrame(updateExplorer)};$('#compare').onclick=()=>{state.compare=!state.compare;$('#compare').textContent=state.compare?'Close comparison':'Compare two products ↗';drawComparison()};$('#radar').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();state.probe={x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height};updateExplorer()};$('#radar').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();state.probe={x:.59,y:.48};updateExplorer()}};drawComparison();}
function updateExplorer(){const fixed=['sun','ap'].includes(state.scene);if(fixed){clearInterval(timer);timer=null;state.playing=false;$('#play').textContent='▶';$('#play').setAttribute('aria-label','Fixed geometry: no teaching animation')}else if(!state.playing)$('#play').setAttribute('aria-label','Play teaching animation');$('#play').disabled=fixed;$('#timeline').disabled=fixed;const p=products.find(p=>p.id===state.product),s=scenes.find(s=>s.id===state.scene);$('#canvas-title').textContent=p.name.toUpperCase();$('#scene-tag').textContent=s.label;$('#product-question').textContent=p.question;$('#product-description').textContent=p.desc;$('#scene-tip').textContent=s.tip;$('#frame-label').textContent=fixed?'FIXED GEOMETRY':`FRAME ${state.frame}/100`;$$('[data-product]').forEach(b=>{b.classList.toggle('active',b.dataset.product===state.product);b.setAttribute('aria-pressed',b.dataset.product===state.product)});setLegend($('#legend'),p);drawRadar($('#radar'),state.product,state.scene,state.frame);if(state.probe){const v=sample(state.probe.x,state.probe.y,state.product,state.scene,state.frame);$('#probe').innerHTML=v===null?'NO ECHO AT THIS SAMPLE<br>Try a colored region.':`ILLUSTRATIVE SAMPLE<br><b>${v.toFixed(p.id==='cc'?3:1)} ${p.unit}</b><br>Not an observed measurement.`}else $('#probe').innerHTML='NO SAMPLE SELECTED<br>Tap the map to investigate.';if(state.compare)drawComparison();}
function drawComparison(){const el=$('#comparison');if(!el)return;if(!state.compare){el.innerHTML='';return}el.innerHTML=`<div class="compare-grid space">${['vel','cc'].map(id=>`<div class="radar-area"><div class="toolbar">${products.find(p=>p.id===id).name.toUpperCase()}</div><div class="radar-wrap"><canvas id="compare-${id}" role="img" aria-label="Simulated ${id==='vel'?'velocity':'correlation coefficient'} for the same scene"></canvas></div><div class="legend" id="legend-${id}"></div></div>`).join('')}</div><p class="tip">Same scene, same time. Rotation and a matching CC drop are useful together; neither color pattern alone establishes a tornado.</p>`;['vel','cc'].forEach(id=>{drawRadar($('#compare-'+id),id,state.scene,state.frame);setLegend($('#legend-'+id),products.find(p=>p.id===id))});}
function gaussian(x,y,cx,cy,sx,sy){return Math.exp(-(((x-cx)/sx)**2+((y-cy)/sy)**2)*2)}
function echo(x,y,scene,frame){const t=frame/100,dx=(t-.5)*.12;let z=0;if(scene==='storm'){z=40*gaussian(x,y,.58+dx,.40,.17,.30)+30*gaussian(x,y,.61+dx,.53,.09,.12)+22*gaussian(x,y,.48+dx,.65,.085,.05)+18*gaussian(x,y,.46+dx,.60,.045,.075)+19*gaussian(x,y,.74+dx,.28,.13,.20);z+=Math.sin(x*111+y*53)*2.1+Math.sin(x*191-y*165)*1.6;z=z>9?z:0;}if(scene==='bats'){const d=Math.hypot((x-.49)*1.15,y-.48),rr=.10+t*.29;z=Math.max(0,1-Math.abs(d-rr)/.034)*40;z*=.8+.2*Math.sin(x*154+y*178);}if(scene==='chaff'){z=40*gaussian(x,y,.46+t*.22,.55-t*.10,.19+t*.10,.11)+22*gaussian(x,y,.35+t*.28,.67-t*.13,.14,.06);z=z>9?z:0;}if(scene==='sun'){const a=Math.atan2(y-.56,x-.42);z=Math.abs(a+2.86)<.021&&x<.42?26:0;}if(scene==='ap'){const d=Math.hypot(x-.42,y-.56);z=d<.31?Math.max(0,Math.sin(x*79+y*23)*Math.cos(y*89-x*21)*40*(1-d/.36)):0;z=z>8?z:0;}return Math.min(68,z)}
function sample(x,y,id,scene,frame){const z=echo(x,y,scene,frame);if(z<5)return null;const dx=(frame/100-.5)*.12,core=gaussian(x,y,.56+dx,.59,.07,.08),hail=gaussian(x,y,.61+dx,.48,.08,.10);if(id==='ref')return z;if(id==='vel'){if(scene==='storm')return Math.max(-60,Math.min(60,((x-.56-dx)/.04)*48*core+(x-.42)*35));if(scene==='bats')return ((x-.42)*.5+(y-.56))*27;if(scene==='ap')return Math.sin(x*100)*2;return (x-.42)*40+(y-.56)*15}if(id==='cc')return scene==='storm'?.985-core*.39-hail*.08:scene==='bats'?.60+.13*Math.sin(x*87+y*49):scene==='chaff'?.48+.1*Math.sin(x*67):scene==='sun'?.56:.66+.12*Math.sin(y*87);if(id==='zdr')return scene==='storm'?2.5*(1-hail)-core:scene==='chaff'?-1.5+2*Math.sin(x*51):scene==='bats'?3:0;if(id==='kdp')return scene==='storm'?Math.max(0,(z-17)/8)*(1-hail*.5):.1;if(id==='sw')return scene==='storm'?1.5+core*9:scene==='bats'?5:scene==='ap'?.5:3;return 0}
function color(v,id){const p=products.find(p=>p.id===id),ranges={ref:[5,65],vel:[-60,60],cc:[.5,1],zdr:[-2,4],kdp:[0,6],sw:[0,12]},[lo,hi]=ranges[id],n=Math.min(6,Math.max(0,(v-lo)/(hi-lo)*6)),i=Math.min(5,Math.floor(n)),f=n-i;const c=p.colors.slice(i,i+2).map(h=>[parseInt(h.slice(1,3),16),parseInt(h.slice(3,5),16),parseInt(h.slice(5,7),16)]);return `rgb(${c[0].map((v,j)=>Math.round(v+(c[1][j]-v)*f)).join(',')})`}
function drawRadar(canvas,id,scene,frame){if(!canvas)return;const w=Math.round(canvas.clientWidth),h=Math.round(canvas.clientHeight);if(w<1||h<1)return;canvas.width=w*devicePixelRatio;canvas.height=h*devicePixelRatio;const c=canvas.getContext('2d');c.scale(devicePixelRatio,devicePixelRatio);c.fillStyle='#111c17';c.fillRect(0,0,w,h);c.strokeStyle='#26372b';c.lineWidth=.7;
// Schematic boundaries provide orientation without implying an actual geographic radar observation.
for(let i=0;i<14;i++){c.beginPath();const yy=(i/12)*h;c.moveTo(0,yy);for(let j=0;j<=8;j++)c.lineTo(j*w/8,yy+Math.sin(i*9+j*7)*h*.025);c.stroke()}for(let i=0;i<13;i++){c.beginPath();const xx=i*w/12;c.moveTo(xx,0);for(let j=0;j<=7;j++)c.lineTo(xx+Math.sin(i*4+j*3)*w*.018,j*h/7);c.stroke()}
c.strokeStyle='#3c4937';c.lineWidth=1;[[[0,.79],[.23,.64],[.43,.56],[.72,.38],[1,.17]],[[.18,0],[.29,.29],[.43,.56],[.59,.78],[.69,1]],[[0,.28],[.4,.32],[.69,.56],[1,.65]]].forEach(path=>{c.beginPath();path.forEach(([x,y],i)=>i?c.lineTo(x*w,y*h):c.moveTo(x*w,y*h));c.stroke()});
const step=3;for(let y=45;y<h-20;y+=step)for(let x=0;x<w;x+=step){const v=sample(x/w,y/h,id,scene,frame);if(v===null)continue;c.globalAlpha=.79+.12*Math.sin(x*17+y*11);c.fillStyle=color(v,id);c.fillRect(x,y,step,step)}c.globalAlpha=1;
const cx=w*.42,cy=h*.56;c.strokeStyle='#b6cc7d2c';c.lineWidth=.8;c.setLineDash([3,5]);[.18,.36,.54,.72].forEach(r=>{c.beginPath();c.arc(cx,cy,h*r,0,Math.PI*2);c.stroke()});c.setLineDash([]);c.strokeStyle='#abc27921';c.beginPath();c.moveTo(cx,0);c.lineTo(cx,h);c.moveTo(0,cy);c.lineTo(w,cy);c.stroke();c.fillStyle='#d0ed80';c.beginPath();c.arc(cx,cy,3,0,7);c.fill();c.font='9px ui-monospace,monospace';c.fillText('RADAR',cx+8,cy+4);c.fillStyle='#9aaa91';c.font='8px ui-monospace,monospace';c.fillText('50 km',cx+4,cy-h*.18+12);c.fillText('100 km',cx+4,cy-h*.36+12);
if(state.probe&&canvas.id==='radar'){const x=state.probe.x*w,y=state.probe.y*h;c.strokeStyle='#ffffff';c.lineWidth=1;c.beginPath();c.arc(x,y,8,0,7);c.moveTo(x-14,y);c.lineTo(x+14,y);c.moveTo(x,y-14);c.lineTo(x,y+14);c.stroke()}}
function basics(){return pageHead('02 / HOW RADAR WORKS','A pulse. An echo.<br><em>A picture of the sky.</em>','Radar sends out radio energy, then listens. What comes back tells us where targets are, how strongly they scatter, and how they move.')+`<div class="grid3"><div class="panel pad"><span class="big-number">01</span><h2>Send a pulse</h2><p>The antenna directs a brief burst of microwave energy into a narrow beam. It rotates and changes elevation to sample the atmosphere.</p></div><div class="panel pad"><span class="big-number">02</span><h2>Listen for echoes</h2><p>Targets scatter some energy back. Return time gives range: distance equals the speed of light multiplied by the round-trip time, divided by two.</p></div><div class="panel pad"><span class="big-number">03</span><h2>Build the scan</h2><p>Echoes are organized by direction and distance. Multiple tilts form a volume; each radar product answers a different question about that volume.</p></div></div><div class="grid2 space"><div class="panel pad"><span class="kicker">TRY IT / TIME OF FLIGHT</span><h2>How far away is the target?</h2><div class="slider-row"><label for="delay">Round-trip delay <b id="delayval">500 μs</b></label><input id="delay" type="range" min="10" max="1600" value="500" step="10"></div><div class="readout"><div><strong id="distance">74.9 km</strong><small>DISTANCE TO TARGET</small></div></div><p>Radio waves travel about 300,000 km each second. Half the travel time is the outward journey.</p>${ref('basics')}</div><div class="panel pad"><span class="kicker">THREE IDEAS, ONE RADAR</span><h2>Doppler and dual-pol are partners.</h2><div class="lesson"><h3>Doppler = motion along the beam</h3><p>Changes in phase between successive pulses reveal radial velocity.</p><button class="text-button" data-go="doppler">Try the motion experiment →</button></div><div class="lesson"><h3>Dual polarization = two orientations</h3><p>Horizontal and vertical information adds clues about target shape and consistency.</p><button class="text-button" data-go="products">Explore the measurements →</button></div></div></div><div class="section-heading"><h2>What the display leaves out</h2></div><div class="grid2"><div class="panel pad"><h3>A scan is a sample in space and time.</h3><p>A low elevation is still above the ground, especially far away. Terrain can block the beam; a widening beam blends small features. The top-down image hides this three-dimensional geometry.</p>${ref('beam')}</div><div class="panel pad"><h3>Different scan strategies, different tradeoffs.</h3><p>Clear-air scans favor sensitivity to weak echoes. Precipitation scans sample storm structure. Volume coverage patterns set the sequence of elevation angles; revisit time varies by operating strategy.</p>${ref('vcp')}</div></div>`;}
function doppler(){return pageHead('03 / DOPPLER LAB','Motion has a <em>point of view.</em>','The radar measures the part of motion toward or away from it. Change the target’s direction and see why a fast wind can register zero.')+`<div class="grid2"><div class="panel pad"><span class="kicker">A TOP-DOWN MOTION EXPERIMENT</span><svg id="doppler-svg" viewBox="0 0 600 380" class="diagram" role="img" aria-label="Radar at left, target at right, and adjustable motion arrow"></svg><p class="tip">Target direction: 0° = directly away; 180° = directly toward. This is a geometric angle, not meteorological wind direction.</p></div><div class="panel pad"><span class="kicker">YOU CONTROL THE TARGET</span><div class="slider-row"><label for="speed">True target speed <b id="speed-val"></b></label><input type="range" id="speed" min="0" max="80" value="40"></div><div class="slider-row"><label for="direction">Angle to the outward beam <b id="direction-val"></b></label><input type="range" id="direction" min="0" max="360" value="45"></div><div class="readout"><div><strong id="radial"></strong><small>MEASURED RADIAL VELOCITY</small></div></div><div class="callout" id="motion-explain" aria-live="polite"></div><div class="row space"><button class="button secondary" data-angle="0">Away</button><button class="button secondary" data-angle="90">Across</button><button class="button secondary" data-angle="180">Toward</button></div><details class="technical-note"><summary>Technical breakdown · radial velocity</summary><p>V<sub>radial</sub> = V<sub>true</sub> × cos(angle). The angle is measured from the outward radar beam. Here, positive is away; negative is toward. Actual product palettes may differ. At 90° or 270°, motion is across the beam and its radial component is zero.</p></details>${ref('velocity')}</div></div><div class="section-heading"><h2>Read motion with context</h2></div><div class="grid3"><div class="panel pad"><span class="kicker">ROTATION</span><h3>Side-by-side opposites</h3><p>A tight inbound/outbound pair can indicate rotation. Its geometry relative to the radar matters. Broad, ordinary wind also makes red and green regions.</p></div><div class="panel pad"><span class="kicker">STORM-RELATIVE VELOCITY</span><h3>Subtract the storm’s travel</h3><p>Removing an estimated storm-motion vector can help expose internal circulation. A wrong motion estimate changes what you see.</p></div><div class="panel pad"><span class="kicker">VELOCITY ALIASING</span><h3>When a scale wraps around</h3><p>Radial speeds beyond the unambiguous limit can fold to the other end of the scale. A sharp color jump can be folded velocity rather than a real wind reversal.</p></div></div>`;}
function drawDoppler(){let speed=+$('#speed').value,angle=+$('#direction').value,r=angle*Math.PI/180,v=speed*Math.cos(r);if(Math.abs(v)<.01)v=0;$('#speed-val').textContent=speed+' m/s';$('#direction-val').textContent=angle+'°';$('#radial').textContent=(v>0?'+':'')+v.toFixed(1)+' m/s';const col=v<0?'#57db91':v>0?'#ee9276':'#b5bdb0';$('#radial').style.color=col;$('#motion-explain').textContent=v===0?(speed===0?'The target is stationary.':'The target moves across the beam. Its radial velocity is zero even though it is moving.'):(v<0?'The target has a component of motion toward the radar.':'The target has a component of motion away from the radar.');const x=390,y=200,len=speed*1.5,ex=x+Math.cos(r)*len,ey=y-Math.sin(r)*len;$('#doppler-svg').innerHTML=`<defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#d0ed80"/></marker></defs><g fill="none" stroke="#2c3b2c"><circle cx="100" cy="200" r="80"/><circle cx="100" cy="200" r="160"/><circle cx="100" cy="200" r="240"/><circle cx="100" cy="200" r="320"/></g><path d="M100 200H550" stroke="#8da65b" stroke-dasharray="5 6"/><circle cx="100" cy="200" r="9" fill="#d0ed80"/><circle cx="390" cy="200" r="9" fill="${col}"/><path d="M${x} ${y}L${ex} ${ey}" stroke="#d0ed80" stroke-width="3" marker-end="url(#arrow)"/><path d="M${x} 250h${v*1.5}" stroke="${col}" stroke-width="7"/><text x="65" y="235" fill="#a9b79b" font-size="12">RADAR</text><text x="350" y="175" fill="#a9b79b" font-size="12">TARGET</text><text x="300" y="310" fill="${col}" font-size="12">RADIAL COMPONENT: ${v.toFixed(1)} m/s</text>`;$('#speed').oninput=drawDoppler;$('#direction').oninput=drawDoppler;$$('[data-angle]').forEach(b=>b.onclick=()=>{$('#direction').value=b.dataset.angle;drawDoppler()});}
function beam(){return pageHead('04 / INSIDE THE BEAM','The farther it looks,<br><em>the higher it sees.</em>','Radar does not skim the surface. Explore how elevation, Earth’s curvature, and beam spreading change what a radar can sample.')+`<div class="panel pad"><div class="grid2"><div><span class="kicker">A VERTICAL SLICE THROUGH THE ATMOSPHERE</span><svg id="beam-svg" class="diagram space" viewBox="0 0 650 350" role="img" aria-label="Radar beam height and width versus distance"></svg></div><div><div class="slider-row"><label for="range">Slant range <b id="range-val"></b></label><input id="range" type="range" min="10" max="240" value="100"></div><div class="slider-row"><label for="tilt">Elevation angle <b id="tilt-val"></b></label><input id="tilt" type="range" min=".5" max="10" value=".5" step=".1"></div><div class="readout"><div><strong id="height-val"></strong><small>BEAM CENTER ABOVE RADAR ALTITUDE</small></div><div><strong id="width-val"></strong><small>APPROXIMATE 1° BEAM WIDTH</small></div></div><div class="callout" id="beam-explain" aria-live="polite"></div></div></div><details class="technical-note"><summary>Technical breakdown · beam geometry</summary><p class="tip">Standard-refraction model: effective Earth radius = 4/3 × 6,371 km. Height = √(r² + R² + 2rR sin θ) − R. Width ≈ 2r tan(0.5°). Radar elevation and terrain are excluded: this is not height above local ground. Vertical scale is exaggerated.</p></details>${ref('beam')}</div><div class="grid3 space"><div class="panel pad"><span class="kicker">OVERSHOOTING</span><h3>Missing low weather</h3><p>A distant low shower or shallow circulation may sit below the beam. An empty radar display does not guarantee an empty sky.</p></div><div class="panel pad"><span class="kicker">BLOCKAGE & RESOLUTION</span><h3>Mountains and blind spots</h3><p>Terrain can intercept the beam. As range increases, a larger sample volume also blends features that a closer radar could separate.</p></div><div class="panel pad"><span class="kicker">ANOMALOUS PROPAGATION</span><h3>The atmosphere bends the beam</h3><p>Strong changes in refractivity can bend the beam toward terrain. A surprising echo can be ground energy, not newly formed rain.</p>${ref('ap')}</div></div>`;}
function drawBeam(){const range=+$('#range').value,tilt=+$('#tilt').value,R=6371*4/3;const h=r=>Math.sqrt(r*r+R*R+2*r*R*Math.sin(tilt*Math.PI/180))-R,height=h(range),width=2*range*Math.tan(Math.PI/360);$('#range-val').textContent=range+' km';$('#tilt-val').textContent=tilt.toFixed(1)+'°';$('#height-val').textContent=height.toFixed(2)+' km';$('#width-val').textContent=width.toFixed(2)+' km';$('#beam-explain').textContent=height>5?'At this range and angle, the beam center is sampling well above low-level weather.':height>2?'The beam is already kilometers above the radar’s altitude; shallow features can be missed.':'Closer and lower scans sample lower levels, while still covering a finite depth.';const maxH=Math.max(8,h(240)*1.15),xp=r=>45+r/240*565,yp=h=>290-h/maxH*245;let center='',upper='',lower='';for(let r=0;r<=240;r+=4){center+=(r?'L':'M')+xp(r)+' '+yp(h(r));upper+=(r?'L':'M')+xp(r)+' '+yp(h(r)+r*Math.tan(Math.PI/360));}for(let r=240;r>=0;r-=4)lower+='L'+xp(r)+' '+yp(Math.max(0,h(r)-r*Math.tan(Math.PI/360)));$('#beam-svg').innerHTML=`<g stroke="#2a3c2a" fill="none">${[0,1,2,3,4].map(i=>`<path d="M45 ${290-i*61}H610"/>`).join('')}</g><path d="${upper+lower}Z" fill="#d0ed8024"/><path d="${center}" fill="none" stroke="#d0ed80" stroke-width="2"/><path d="M45 290H610" stroke="#8b9d6b"/><path d="M${xp(range)} 290V${yp(height)}" stroke="#e9eece" stroke-dasharray="4 4"/><circle cx="${xp(range)}" cy="${yp(height)}" r="5" fill="#d0ed80"/><g font-size="10" fill="#a3b093"><text x="35" y="313">0</text><text x="275" y="313">100</text><text x="510" y="313">200 km</text><text x="14" y="50">${maxH.toFixed(0)}</text><text x="14" y="180">${(maxH/2).toFixed(0)}</text><text x="14" y="290">0</text><text x="45" y="28">HEIGHT ABOVE RADAR (km)</text><text x="${Math.min(480,xp(range)+10)}" y="${Math.max(35,yp(height)-12)}">${height.toFixed(2)} km</text></g>`;$('#range').oninput=drawBeam;$('#tilt').oninput=drawBeam;}
const archiveImages={chaff:{url:'https://www.weather.gov/images/ilm/climate/chaff/Z_CCloop.gif',alt:'NWS Wilmington original reflectivity and correlation coefficient loop, April 22, 2016'},duct:{url:'https://www.noaa.gov/sites/default/files/2023-08/ducting_hgx.png',alt:'NOAA original Houston radar image showing ducting on August 2, 2023'}};
let caseFilter='All';
function caseList(){return pageHead('05 / UNUSUAL ECHOES','Strange on screen.<br><em>Explainable in the sky.</em>','Real documented observations, with the evidence that explains them. Explore a case, examine the clues, and try a simplified reconstruction.','EVIDENCE BEFORE ASSUMPTIONS')+`<div class="callout">“Anomaly” means unexpected—not unexplained. A radar image records received energy; it does not establish what caused a weather event.</div><div class="filters">${['All','Biological','Human-made','Instrument & atmosphere','Severe weather'].map(f=>`<button class="filter ${caseFilter===f?'active':''}" data-filter="${f}" aria-pressed="${caseFilter===f}">${f}</button>`).join('')}</div><div class="case-grid">${cases.filter(c=>caseFilter==='All'||caseFilter===c.type).map(c=>`<article class="case-card"><canvas class="case-art" data-case-art="${c.id}" role="img" aria-label="Schematic illustration of ${c.title}; not original radar data"></canvas><div class="pad"><span class="kicker">${c.type.toUpperCase()}</span><h3>${c.title}</h3><span class="scan-badge">${c.where} · ${c.date}</span><p>${c.summary}</p><button class="text-button" data-case="${c.id}">Open the case file ↗</button></div></article>`).join('')}</div><p class="tip">Gallery thumbnails and reconstructions are schematic illustrations, not archival scans. Original observations and imagery are on the linked agency pages.</p>`;}
function drawCaseArts(){$$('[data-case-art]').forEach(canvas=>{const cs=cases.find(c=>c.id===canvas.dataset.caseArt);drawRadar(canvas,'ref',cs.scene,55)});$$('[data-filter]').forEach(b=>b.onclick=()=>{caseFilter=b.dataset.filter;render()});$$('[data-case]').forEach(b=>b.onclick=()=>caseDetail(b.dataset.case));}
function caseDetail(id){const cs=cases.find(c=>c.id===id);$('#page').innerHTML=`<button class="back" id="back-cases">← All unusual echoes</button>`+pageHead('05 / CASE FILE',cs.title,`${cs.where} · ${cs.date}`,cs.type.toUpperCase())+`<div class="grid2 case-detail"><div class="panel"><canvas id="case-canvas" class="case-art" role="img" aria-label="Conceptual reconstruction of ${cs.title}, not original event data"></canvas><div class="pad"><span class="kicker">SCHEMATIC RECONSTRUCTION</span><p>Use this illustration to understand the pattern. The original radar observations, imagery, and agency explanation are in the source record.</p>${ref(cs.src)}<div class="row space"><button class="button" id="try-case">Try this pattern in the explorer →</button></div></div></div><div class="panel pad">${archiveImages[id]?`<figure class="archive"><img src="${archiveImages[id].url}" alt="${archiveImages[id].alt}" loading="lazy"><figcaption>ORIGINAL AGENCY IMAGERY · ${ref(cs.src)}<br>Historical observation, not current weather. If the remote image is unavailable, open the source record above.</figcaption></figure>`:''}<span class="kicker">THE EVIDENCE FILE</span>${[['OBSERVED',cs.observed],['EXPLANATION',cs.explanation],['KEY CLUES',cs.clues],['LIMITS',cs.limit]].map(([h,t])=>`<div class="evidence"><strong>${h}</strong><p>${t}</p></div>`).join('')}<p class="tip">Agency documentation supports this particular interpretation. Similar-looking patterns elsewhere need their own evidence.</p></div></div><div class="panel pad space"><span class="kicker">HOW TO INVESTIGATE A SURPRISING RETURN</span><div class="checklist"><p>Find the radar location, product, timestamp, elevation angle, and original sequence.</p><p>Compare reflectivity, velocity, and dual-pol clues at the same place and time.</p><p>Check nearby radars, satellite imagery, weather observations, and agency notes.</p><p>State what the evidence supports, and keep remaining uncertainty visible.</p></div></div>`;drawRadar($('#case-canvas'),'ref',cs.scene,55);$('#back-cases').onclick=()=>go('cases');$('#try-case').onclick=()=>{state.scene=cs.scene;state.product='ref';state.frame=55;go('explore')};window.scrollTo(0,0);}
function productPage(){return pageHead('09 / PRODUCT FIELDGUIDE','One radar.<br><em>Many ways to see.</em>','Start with the question you want to answer. Each product has strengths, blind spots, and a reason to use it alongside the others.')+`<div class="product-grid">${products.map(p=>`<article class="product-card"><span class="kicker">${p.code} / ${p.unit}</span><h2>${p.name}</h2><span class="simple-label">IN PLAIN LANGUAGE</span><p>${productPlain[p.id]}</p><details class="technical-note"><summary>Technical breakdown · ${p.code}</summary><p>${p.desc}</p><p><b>Display units:</b> ${p.id==='cc'?'unitless coefficient (ρhv)':p.unit}. Read the legend supplied with the original product; the explorer uses a teaching palette.</p></details><div class="colorbar" style="background:linear-gradient(to right,${p.colors})"></div><dl><dt>USE IT FOR</dt><dd>${p.use}</dd><dt>WATCH OUT FOR</dt><dd>${p.limit}</dd></dl><div class="row"><button class="text-button" data-try-product="${p.id}">Try this lens →</button>${ref(p.src)}</div></article>`).join('')}</div><div class="section-heading"><h2>Beyond the six lenses</h2></div><div class="grid2">${[
['Differential phase · ΦDP','The horizontal–vertical phase difference accumulates along the path. Its range gradient is used to derive KDP.','products'],
['Hydrometeor classification · HCA','An algorithm combines radar variables and environmental information to suggest categories such as rain, snow, hail, or biological targets. Categories are estimates.','products'],
['Rain rate & accumulation · QPE','Algorithms convert radar information into estimated rainfall rates and totals. Beam height, hail, melting snow, and calibration affect results; gauges add ground truth.','products'],
['Composite reflectivity & echo tops','A composite uses the strongest reflectivity in a column. Echo tops estimate the height of a selected echo threshold. Neither is a direct view of surface weather.','nexrad'],
['Multi-radar multi-sensor · MRMS','Combines radar and other observations into broader analyses. Filtering can remove non-weather echoes, so a mosaic may differ from an individual radar.','chaff'],
['Radar, satellite, and lightning','Radar measures backscatter; satellites observe radiance from above; lightning systems detect electrical activity. They provide different pieces of the same storm story.','basics']
].map(([title,desc,s])=>`<div class="panel pad"><h3>${title}</h3><p>${desc}</p>${ref(s)}</div>`).join('')}</div><div class="panel pad space"><span class="kicker">PICK THE RIGHT INSTRUMENT</span><h2>“Radar” is a family, not a single tool.</h2><div class="prose">NEXRAD WSR-88D weather radars scan large atmospheric volumes. Terminal Doppler Weather Radar supports aviation wind-hazard detection near selected airports. Smaller X-band weather radars can fill local observing needs but face different attenuation tradeoffs. Phased-array research explores electronic beam steering and faster sampling. Marine, air-traffic, and speed-enforcement radars have other designs and purposes; their displays are not interchangeable.</div><p>${ref('nexrad')} · ${ref('tdwr')} · ${ref('par')}</p></div><div class="panel pad space"><span class="kicker">PUT IT INTO PRACTICE</span><h3>Ready to compare your learning with actual observations?</h3><p>The official viewer opens separately with current radar and timestamps. This fieldguide combines historical observations with a teaching simulator; it does not display current hazards or issue alerts.</p><a class="button" href="https://radar.weather.gov/" target="_blank" rel="noopener">Open official NWS live radar ↗</a></div>`;}
const questions=[
{q:'The target moves at 40 m/s exactly across the radar beam. What radial speed should this idealized radar measure?',a:['About 40 m/s away','About 0 m/s','About 40 m/s toward'],correct:1,why:'Radial velocity is only the component along the beam. At 90°, cos(90°) = 0. The target is moving, but its distance from the radar is momentarily not changing.',topic:'doppler'},
{q:'A strong reflectivity echo appears near a known cave at dusk and expands outward. What should you do next?',a:['Conclude that a thunderstorm is forming','Declare a tornado because it is a ring','Check biological clues, dual-pol, timing, and independent observations'],correct:2,why:'Bats can make surprisingly strong returns. Geometry and timing suggest a hypothesis; other radar products and independent evidence help test it.',topic:'cases'},
{q:'You see a patch of low correlation coefficient. Does that confirm a tornado?',a:['Yes, all low CC is debris','No. Check for co-located rotation, storm echo, and supporting context','No, tornadoes always have high CC'],correct:1,why:'Low CC has many causes. A tornado debris signature needs matching strong rotation and appropriate storm context. Some tornadoes have no visible debris signature.',topic:'products'},
{q:'At a low scan angle, what usually happens to the beam as range increases?',a:['It becomes higher and wider','It stays at the same height and width','It becomes narrower and follows the ground'],correct:0,why:'Earth curvature and scan elevation lift the beam relative to the surface, while spreading increases the sampled volume. Distant low features can be missed.',topic:'beam'},
{q:'A narrow spike appears for a scan near sunset and points toward the setting sun. What is a plausible explanation?',a:['Solar interference entering the radar receiver','A laser creating a storm','A fault line visible in the atmosphere'],correct:0,why:'Solar radio energy can produce radial spikes when a radar points toward the low sun. Confirm timing and direction; other interference can also cause streaks.',topic:'cases'},
{q:'Why can an individual radar show a chaff echo that a processed mosaic removes?',a:['The mosaic uses different weather laws','A quality-control algorithm can reject non-weather echoes','Chaff instantly disappears between products'],correct:1,why:'Products may apply different processing and quality control. NWS Wilmington documented MRMS removing chaff echoes using dual-pol information.',topic:'products'},
{q:'A bright-red reflectivity core appears. What can you establish from that color alone?',a:['The exact hailstone diameter','A tornado is on the ground','The echo is strong on that product’s scale'],correct:2,why:'Reflectivity measures returned energy, with multiple possible target populations. Use the legend, other products, and observations to infer precipitation type or hazards.',topic:'explore'},
{q:'Why can an empty distant radar display still coexist with a shallow shower?',a:['Radar always sees the surface','The beam may pass above the shower','Doppler cannot detect water'],correct:1,why:'The beam rises with range and can overshoot shallow precipitation. Terrain, sensitivity, and sampling also matter.',topic:'beam'},
{q:'A sharp green-to-red jump appears in velocity. Is it necessarily rotation?',a:['Yes, any red next to green proves rotation','No, it could involve aliasing, geometry, or other wind patterns','It must be instrument damage'],correct:1,why:'Aliased velocity can wrap between ends of the scale. Rotation assessment needs the geometry, continuity, and other observations.',topic:'doppler'},
{q:'What is the strongest approach to an extraordinary claim based on a radar screenshot?',a:['Identify the shape and assume its cause','Trust whichever caption is most confident','Recover the original sequence and compare products and independent observations'],correct:2,why:'A screenshot discards time, product details, and observational context. Establish those first, then test competing explanations against independent evidence.',topic:'cases'}];
let qi=0,score=0,answered=false,quizDone=false;
function quiz(){if(quizDone)return pageHead('10 / TEST YOUR EYE','A sharper eye.<br><em>A better question.</em>','You’ve completed the radar check. Revisit the labs to strengthen the ideas that felt less familiar.')+`<div class="panel pad quizbox"><span class="big-number">${score} / ${questions.length}</span><h2>${score>=8?'You’re connecting the clues.':'Keep building your radar instincts.'}</h2><p>These are learning questions, not a forecasting qualification. The best radar habit is to compare products and test your interpretation.</p><div class="row"><button class="button" id="restart-quiz">Try again</button><button class="button secondary" data-go="explore">Back to the explorer</button></div></div>`;const q=questions[qi];return pageHead('10 / TEST YOUR EYE','Look. Think.<br><em>Follow the evidence.</em>','Ten quick questions about real interpretation habits. Get an explanation after every answer.')+`<div class="panel pad quizbox"><div class="progress"><span style="width:${qi/questions.length*100}%"></span></div><div class="section-top"><span class="kicker">QUESTION ${qi+1} / ${questions.length}</span><span class="scan-badge">${score} CORRECT SO FAR</span></div><h2>${q.q}</h2><div class="answers">${q.a.map((a,i)=>`<button class="answer" data-answer="${i}">${String.fromCharCode(65+i)} <span class="dot">/</span> ${a}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div></div>`;}
function quizBind(){if($('#restart-quiz'))$('#restart-quiz').onclick=()=>{qi=0;score=0;quizDone=false;answered=false;render()};$$('[data-answer]').forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const q=questions[qi],n=+b.dataset.answer,ok=n===q.correct;if(ok)score++;$$('[data-answer]').forEach((x,i)=>{x.disabled=true;if(i===q.correct)x.classList.add('correct');else if(i===n)x.classList.add('wrong')});$('#feedback').innerHTML=`<div class="feedback"><span class="kicker">${ok?'CORRECT':'LET’S UNPACK THAT'}</span><p>${q.why}</p><div class="row"><button class="button" id="next-question">${qi===questions.length-1?'See my results':'Next question →'}</button><button class="text-button" data-go="${q.topic}">Revisit this topic ↗</button></div></div>`;bind();$('#next-question').onclick=()=>{qi++;answered=false;if(qi>=questions.length)quizDone=true;render()}});}
const glossary=[['Aliasing','A measurement exceeding an unambiguous interval appears wrapped into another part of the scale; velocity folding is a familiar radar example.'],['Anomalous propagation (AP)','Unexpected propagation of radar energy, often producing non-precipitation surface echoes. Superrefraction and ducting can amplify ground returns.'],['Attenuation','Loss of radar energy along the path. It can weaken echoes behind intervening targets; its severity depends on wavelength and conditions.'],['Bright band','Enhanced reflectivity near the melting layer, where partially melted snow can scatter strongly. It can bias rainfall estimates.'],['Clutter','Returns from targets that are unwanted for the observing task, such as ground features when measuring precipitation. Those targets can still be scientifically interesting.'],['Couplet','Neighboring inbound and outbound radial velocity regions. A tight, appropriately oriented pair can support rotation; context and data quality matter.'],['dBZ','A logarithmic scale of equivalent radar reflectivity factor. Larger positive values represent stronger echoes, not a unique precipitation type.'],['Dual polarization','Radar observations in horizontal and vertical polarizations that add information about scatterer properties.'],['Elevation angle / tilt','The angle of the radar beam above the local horizontal. A volume scan typically samples multiple elevations.'],['Gate / range bin','A radial sampling interval used to organize returned radar information. It represents a volume, not a single raindrop.'],['Hook echo','A curved reflectivity appendage often associated with a supercell’s circulation. Its presence alone does not establish a tornado.'],['Hydrometeor','A water or ice particle in the atmosphere, such as a raindrop, snowflake, or hailstone.'],['NEXRAD / WSR-88D','The U.S. operational network and Weather Surveillance Radar–1988 Doppler system used for weather observations.'],['Nyquist velocity','The maximum unambiguous radial velocity magnitude for a particular radar sampling strategy.'],['Radial velocity','The component of target motion along the radar’s line of sight, toward or away from the antenna.'],['Reflectivity','A measure derived from backscattered radar energy, commonly displayed as equivalent reflectivity in dBZ.'],['Storm-relative velocity','Radial velocity after removing an estimated storm-motion component, helping reveal motion within the storm.'],['Tornado debris signature (TDS)','A radar signature involving low correlation coefficient co-located with strong rotation and an appropriate storm echo, supporting lofted debris.'],['Volume coverage pattern (VCP)','A radar’s sequence of scan elevations and sampling strategies used to build a three-dimensional atmospheric observation.']];
function library(){return pageHead('11 / GLOSSARY & SOURCES','Less jargon.<br><em>More understanding.</em>','A plain-language reference and the original science behind this fieldguide. Source records were reviewed October 29, 2026.')+`<div class="grid2"><section><h2 style="font-weight:400">Find a radar term</h2><input class="search" id="glossary-search" aria-label="Search radar glossary" placeholder="Try ‘aliasing’, ‘dBZ’, or ‘hook’…"><div id="glossary-list">${glossaryHTML('')}</div></section><section class="panel pad"><span class="kicker">THE ORIGINAL RECORD</span><h2>Go straight to the science.</h2><p>Educational explanations are paraphrased from official resources. Case dates and interpretations apply to the particular examples documented by those agencies.</p>${Object.values(sources).map(([name,url])=>`<a class="source-item" href="${url}" target="_blank" rel="noopener"><strong>${name} ↗</strong><small>${new URL(url).hostname}</small></a>`).join('')}<div class="callout">Independent educational site. Not affiliated with or endorsed by NOAA or NWS. Actual-observation panels show credited historical agency imagery. Simulator fields and sample values are synthetic. Neither view is a forecast or alert.</div></section></div>`;}
function glossaryHTML(query){const filtered=glossary.filter(g=>g.join(' ').toLowerCase().includes(query.toLowerCase()));return filtered.length?filtered.map(([t,d])=>`<details><summary>${t}</summary><p>${d}</p></details>`).join(''):'<p class="empty">No matching term. Try a shorter word.</p>';}
const originalBind=bind;bind=function(){originalBind();if(state.page==='basics'&&$('#delay'))$('#delay').oninput=()=>{const d=+$('#delay').value;$('#delayval').textContent=d+' μs';$('#distance').textContent=(299792.458*d/1e6/2).toFixed(1)+' km'};if(state.page==='products')$$('[data-try-product]').forEach(b=>b.onclick=()=>{state.product=b.dataset.tryProduct;observationMode='sim';go('explore')});if(state.page==='quiz')quizBind();if(state.page==='library')$('#glossary-search').oninput=e=>{$('#glossary-list').innerHTML=glossaryHTML(e.target.value)};};
document.querySelector('.brand').onclick=e=>{e.preventDefault();go('explore')};
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(state.page==='explore')updateExplorer();if(state.page==='cases'){if($('#case-canvas')){const scene=$('#try-case');/* detail retains its illustration on next navigation */}else drawCaseArts()}},150)});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#workspace')?.classList.contains('full-lab')){$('#workspace').classList.remove('full-lab');updateExplorer()}});render();
